import{xt as e}from"./index-CS4Co4Dw.js";async function t(t={}){return(await e.get(`/sales`,{params:t})).data}async function n(t){return(await e.get(`/sales/${t}`)).data}async function r(){return(await e.get(`/sales/next-code`)).data.code}async function i(t){return(await e.post(`/sales`,t)).data}async function a(t,n){return(await e.put(`/sales/${t}`,n)).data}async function o(t){return(await e.delete(`/sales/${t}`)).data}export{t as a,n as i,o as n,a as o,r,i as t};